basic.code:
// The four categories of the shop
{"table": "categories", "select": "name", "order": "name"}
// Every product: one GET request per query
{"table": "products", "select": "name,price,stock", "order": "name"}

// Without "select" you get every column, id and created_at too
{"table": "customers", "order": "name", "limit": 3}
// With "select": only the columns you ask for, in that order
{"table": "customers", "select": "name,city,joined", "order": "name"}

// eq: customers from Madrid
{"table": "customers", "select": "name,city", "where": {"city": "eq.Madrid"}, "order": "name"}
// Without an operator, the filter is eq
{"table": "orders", "select": "ordered,status,total", "where": {"status": "shipped"}, "order": "ordered"}
// neq: every order that is not shipped
{"table": "orders", "select": "ordered,status,total", "where": {"status": "neq.shipped"}, "order": "ordered"}

// gt: more than 5 euros, dearest first
{"table": "products", "select": "name,price", "where": {"price": "gt.5"}, "order": "price.desc"}
// lte: 15 units or fewer left
{"table": "products", "select": "name,stock", "where": {"stock": "lte.15"}, "order": "stock,name"}
// gte on a date: customers who joined in 2024 or later
{"table": "customers", "select": "name,joined", "where": {"joined": "gte.2024-01-01"}, "order": "joined"}

// Two filters: a row must pass both (AND)
{"table": "products", "select": "name,category_id,price", "where": {"category_id": 1, "price": "lt.2"}, "order": "price"}
// Three filters: active, in stock and under 3 euros
{"table": "products", "select": "name,price,stock", "where": {"active": "is.true", "stock": "gt.0", "price": "lt.3"}, "order": "price"}

// in.(…): any of several values
{"table": "customers", "select": "name,city", "where": {"city": "in.(Madrid,London)"}, "order": "city,name"}
{"table": "orders", "select": "ordered,status,total", "where": {"status": "in.(new,paid)"}, "order": "ordered"}
// Numbers too: the drinks (2) and the fruit (4)
{"table": "products", "select": "name,category_id,price", "where": {"category_id": "in.(2,4)"}, "order": "category_id,name"}

// like: % is any text and capitals count
{"table": "products", "select": "name", "where": {"name": "like.Gr%"}, "order": "name"}
{"table": "products", "select": "name", "where": {"name": "like.gr%"}, "order": "name"}
// _ is exactly one character
{"table": "products", "select": "name,price", "where": {"name": "like.% _ kg"}, "order": "name"}
// ilike ignores capitals: surnames ending in "ez"
{"table": "customers", "select": "name,city", "where": {"name": "ilike.%EZ"}, "order": "name"}

// is.null: the customer without an email
{"table": "customers", "select": "name,email,city", "where": {"email": "is.null"}}
// neq leaves out NULL: 6 reviews, not 7
{"table": "reviews", "select": "rating,comment", "where": {"comment": "neq.Sweet"}, "order": "rating,comment"}
// is.false / is.true on a boolean column
{"table": "products", "select": "name,stock,active", "where": {"active": "is.false"}}
{"table": "products", "select": "name,stock,active", "where": {"active": "is.true", "stock": 0}}

// The five dearest products
{"table": "products", "select": "name,price", "order": "price.desc", "limit": 5}
// Two columns: by category, then dearest first inside each one
{"table": "products", "select": "category_id,name,price", "order": "category_id,price.desc"}

// Four products per page, always in the same order
// Page 1
{"table": "products", "select": "name,price", "order": "name", "limit": 4}
// Page 2: skip the first 4
{"table": "products", "select": "name,price", "order": "name", "limit": 4, "offset": 4}
// Page 3: skip 8
{"table": "products", "select": "name,price", "order": "name", "limit": 4, "offset": 8}

// limit 0: no rows, only how many there are
{"table": "orders", "limit": 0}
{"table": "orders", "where": {"status": "paid"}, "limit": 0}
{"table": "customers", "where": {"city": "Madrid"}, "limit": 0}
// The count is the total, not the page: 2 rows of 4
{"table": "orders", "select": "ordered,status,total", "where": {"status": "shipped"}, "order": "ordered", "limit": 2}

// tags is a json column: it comes back as a list
{"table": "products", "select": "name,tags", "where": {"category_id": 1}, "order": "name"}
// like searches the text of the list
{"table": "products", "select": "name,tags", "where": {"tags": "like.%sweet%"}, "order": "name"}
// An empty list
{"table": "products", "select": "name,tags", "where": {"tags": "eq.[]"}}

// POST /tables/products with one object
{"table": "products", "insert": {"name": "Muffin", "category_id": 1, "price": 2.25, "tags": ["sweet"]}}
// The server filled in id, created_at, stock and active
{"table": "products", "select": "name,price,stock,active,tags", "where": {"category_id": 1}, "order": "price"}

// A list: several rows in one request
{"table": "customers", "insert": [
  {"name": "Lucía Romero", "email": "lucia@example.com", "city": "Madrid", "joined": "2024-06-01"},
  {"name": "Tom Wilson", "email": "tom@example.com", "city": "London", "joined": "2024-06-03"},
  {"name": "Irene Vega", "city": "Valencia", "joined": "2024-06-10"}
]}
{"table": "customers", "select": "name,email,city,joined", "where": {"joined": "gte.2024-05-01"}, "order": "joined"}

// Change one customer: the unique email picks the row
{"table": "customers", "update": {"where": {"email": "luis@example.com"}, "set": {"city": "Malaga"}}}
// Several columns at once
{"table": "customers", "update": {"where": {"email": "john@example.com"}, "set": {"city": "Leeds", "email": "john.smith@example.com"}}}
{"table": "customers", "select": "name,email,city", "where": {"name": "in.(Luis Pérez,John Smith)"}, "order": "name"}

// Every product without stock stops being sold
{"table": "products", "update": {"where": {"stock": 0}, "set": {"active": false}}}
// Every new order is now paid
{"table": "orders", "update": {"where": {"status": "new"}, "set": {"status": "paid"}}}
{"table": "orders", "select": "ordered,status,total", "where": {"status": "paid"}, "order": "ordered"}

// Delete the reviews of 3 stars or fewer
{"table": "reviews", "delete": {"where": {"rating": "lte.3"}}}
// And the ones without a comment
{"table": "reviews", "delete": {"where": {"comment": "is.null"}}}
{"table": "reviews", "select": "product_id,rating,comment", "order": "rating.desc,product_id"}

// Dates are YYYY-MM-DD: gte, lt and order work as expected
{"table": "orders", "select": "ordered,status,total", "where": {"ordered": "gte.2024-05-01"}, "order": "ordered"}
// A whole month with like
{"table": "orders", "select": "ordered,status,total", "where": {"ordered": "like.2024-04%"}, "order": "ordered"}
// Customers before 2024, newest first
{"table": "customers", "select": "name,joined", "where": {"joined": "lt.2024-01-01"}, "order": "joined.desc"}

// No joins: first the lines of order 1…
{"table": "order_items", "select": "product_id,qty,price", "where": {"order_id": 1}, "order": "product_id"}
// …then the reviews of those products, with the ids from the first answer
{"table": "reviews", "select": "product_id,rating,comment", "where": {"product_id": "in.(1,7,9)"}, "order": "product_id,rating.desc"}

// The menu: the categories by name
{"table": "categories", "select": "name", "order": "name"}
// The shop window: what can be sold, cheapest first, 6 per page
{"table": "products", "select": "name,price,stock,tags", "where": {"active": "is.true", "stock": "gt.0"}, "order": "price,name", "limit": 6}
// Page 2
{"table": "products", "select": "name,price,stock,tags", "where": {"active": "is.true", "stock": "gt.0"}, "order": "price,name", "limit": 6, "offset": 6}

advanced.code:
// Each query is one HTTP request to /api/v1/<ref>/tables/<table>
// GET …/tables/products?price=gte.2&active=is.true&order=price.desc&limit=5&select=name,price,stock
{"table": "products", "select": "name,price,stock", "where": {"price": "gte.2", "active": "is.true"}, "order": "price.desc", "limit": 5}
// GET …/tables/orders?status=eq.paid&order=ordered&select=ordered,total&limit=100
{"table": "orders", "select": "ordered,total", "where": {"status": "paid"}, "order": "ordered"}

// Every shop table is "public_read": the anon key alone can read it
{"table": "categories", "select": "name", "order": "name"}
{"table": "reviews", "select": "product_id,rating,comment", "where": {"rating": 5}, "order": "product_id"}
// "notes" is "owner": a user sees only their own rows
// (the course user has none yet)
{"table": "notes", "select": "title,done"}

// Signed in (Authorization: Bearer <token>), the user can write
{"table": "reviews", "insert": [
  {"product_id": 3, "rating": 5, "comment": "Proper rye"},
  {"product_id": 3, "rating": 4, "comment": "Dense, as it should be"}
]}
{"table": "reviews", "update": {"where": {"comment": "Not ripe"}, "set": {"rating": 3}}}
{"table": "reviews", "select": "product_id,rating,comment", "where": {"product_id": "in.(3,12)"}, "order": "product_id,rating.desc"}

// Ana is signed in: her rows get her owner_id
{"table": "notes", "insert": [
  {"title": "Order flour", "body": "25 kg for Monday"},
  {"title": "Call the dairy", "body": "Milk arrived late", "done": true},
  {"title": "New prices", "body": "Check the coffee"}
]}
// She lists the table and sees only her own notes
{"table": "notes", "select": "title,body,done", "order": "title"}

// Luis is signed in: Ana's notes are not there for him
{"table": "notes", "where": {"title": "Order flour"}, "limit": 0}
{"table": "notes", "insert": {"title": "Shelf for the jams"}}
// A filter only reaches his own rows: Ana's done notes stay as they are
{"table": "notes", "update": {"where": {"done": false}, "set": {"done": true}}}
{"table": "notes", "select": "title,done", "order": "title"}

// Ana: owner_id is filled in by the server, whatever you send
{"table": "notes", "insert": [
  {"title": "Pay the rent", "done": true},
  {"title": "Count the till", "owner_id": 1},
  {"title": "Paint the sign"}
]}
// She can change and delete her own rows
{"table": "notes", "update": {"where": {"title": "Count the till"}, "set": {"done": true}}}
{"table": "notes", "delete": {"where": {"title": "Pay the rent"}}}
{"table": "notes", "select": "title,done,owner_id", "order": "title"}

// A to-do list per user: list, add, tick and clear
{"table": "notes", "insert": [
  {"title": "Bake 40 baguettes"},
  {"title": "Clean the oven"},
  {"title": "Write the menu"}
]}
// Tick one off
{"table": "notes", "update": {"where": {"title": "Clean the oven"}, "set": {"done": true}}}
// The screen: pending first, then the done ones
{"table": "notes", "select": "title,done", "order": "done,title"}

// A stable order: price can tie, so add a second column
{"table": "products", "select": "name,price", "order": "price,name", "limit": 5}
// Page 2: offset = (page - 1) * size
{"table": "products", "select": "name,price", "order": "price,name", "limit": 5, "offset": 5}
// The last page: count 12, size 5 → 3 pages, offset 10
{"table": "products", "select": "name,price", "order": "price,name", "limit": 5, "offset": 10}
// Past the end: no rows, the count stays
{"table": "products", "select": "name,price", "order": "price,name", "limit": 5, "offset": 15}

// No count(): limit 0 brings back only the total
{"table": "products", "limit": 0}
{"table": "products", "where": {"active": "is.true", "stock": "gt.0"}, "limit": 0}
{"table": "products", "where": {"stock": "lt.15"}, "limit": 0}
{"table": "reviews", "where": {"rating": "gte.4"}, "limit": 0}
// A badge with "3 low stock" needs the rows only when it is opened
{"table": "products", "select": "name,stock", "where": {"stock": "lt.15"}, "order": "stock,name"}

// No GROUP BY: one count per status, one request each
{"table": "orders", "where": {"status": "new"}, "limit": 0}
{"table": "orders", "where": {"status": "paid"}, "limit": 0}
{"table": "orders", "where": {"status": "shipped"}, "limit": 0}
{"table": "orders", "where": {"status": "cancelled"}, "limit": 0}
// Or one request and the app counts: 10 short rows
{"table": "orders", "select": "status,total", "order": "status,total"}

// No sum(): bring back just the column to add up
{"table": "orders", "select": "ordered,total", "where": {"status": "neq.cancelled"}, "order": "ordered"}
// The lines of order 6: qty × price, added up in the app
{"table": "order_items", "select": "product_id,qty,price", "where": {"order_id": 6}, "order": "product_id"}

// orders.total is stored (denormalised): reading an order is one request
// Order 7 has 6 croissants at 1.50 = 9.00; add 2 yogurts at 2.40
{"table": "order_items", "insert": {"order_id": 7, "product_id": 8, "qty": 2, "price": 2.4}}
{"table": "order_items", "select": "product_id,qty,price", "where": {"order_id": 7}, "order": "product_id"}
// The app adds up 9.00 + 4.80 and saves the new total
{"table": "orders", "update": {"where": {"customer_id": 2, "ordered": "2024-05-12"}, "set": {"total": 13.8}}}
{"table": "orders", "select": "customer_id,ordered,status,total", "where": {"customer_id": 2}, "order": "ordered"}

// name and price are required (not null); stock has a default
{"table": "products", "insert": {"name": "Brioche", "category_id": 1, "price": 3.1}}
{"table": "products", "select": "name,price,stock,active", "where": {"name": "Brioche"}}
// Without a name the database says no
{"table": "products", "insert": {"category_id": 1, "price": 2.5}}

// customers.email is unique: one account per address
{"table": "customers", "insert": {"name": "Nora Gil", "email": "nora@example.com", "city": "Bilbao"}}
{"table": "customers", "select": "name,email,city", "where": {"city": "Bilbao"}, "order": "name"}
// The same email again: the database refuses it
{"table": "customers", "insert": {"name": "Nora Gil Ruiz", "email": "nora@example.com"}}

// "where" is a JSON object: one filter per column.
// A second "ordered" key would replace the first, so for a range:
// 1) a month or a year, with like
{"table": "orders", "select": "ordered,status,total", "where": {"ordered": "like.2024-05%"}, "order": "ordered"}
// 2) from a date, sorted, and the app stops at the end of the range
{"table": "orders", "select": "ordered,status,total", "where": {"ordered": "gte.2024-03-10"}, "order": "ordered", "limit": 4}
// 3) a range on one column and a filter on another
{"table": "orders", "select": "ordered,status,total", "where": {"ordered": "lt.2024-05-01", "total": "gt.12"}, "order": "ordered"}

// db.table('products').list(where: {'category_id': 2}, order: 'price.desc')
{"table": "products", "where": {"category_id": 2}, "order": "price.desc", "select": "name,price,stock"}
// db.table('products').list(where: {'name': 'ilike.%e%', 'active': 'is.true'}, order: 'name', limit: 4, offset: 4)
{"table": "products", "where": {"name": "ilike.%e%", "active": "is.true"}, "order": "name", "limit": 4, "offset": 4, "select": "name,price"}

// final row = await db.table('categories').insert({'name': 'Frozen'});
{"table": "categories", "insert": {"name": "Frozen"}}
// await db.table('categories').update(row['id'], {'name': 'Frozen food'});
{"table": "categories", "update": {"where": {"name": "Frozen"}, "set": {"name": "Frozen food"}}}
// await db.table('categories').list(order: 'name')
{"table": "categories", "select": "name", "order": "name"}
// await db.table('categories').delete(row['id']);
{"table": "categories", "delete": {"where": {"name": "Frozen food"}}}
{"table": "categories", "select": "name", "order": "name"}

// await db.signIn('ana@…', password);   (the studio signs in as Ana)
// await db.table('notes').insert({'title': 'Reorder jam'});
{"table": "notes", "insert": {"title": "Reorder jam", "body": "Strawberry, 12 jars"}}
{"table": "notes", "insert": {"title": "Holiday rota"}}
// final notes = await db.table('notes').list(order: 'title');
{"table": "notes", "select": "title,body,done", "order": "title"}

// The app ships the anon key: rules apply. Reading the shop is public…
{"table": "employees", "select": "name,role", "order": "name"}
// …so anything sensitive must not live in a public_read table:
// anyone with the anon key can read it (salaries!)
{"table": "employees", "select": "name,role,salary", "where": {"salary": "gte.3000"}, "order": "salary.desc"}

// The "My orders" screen of customer 1, step by step
// 1) The list: newest first, with the stored total
{"table": "orders", "select": "ordered,status,total", "where": {"customer_id": 1}, "order": "ordered.desc"}
// 2) She taps the order of 15 March (order 3): its lines
{"table": "order_items", "select": "product_id,qty,price", "where": {"order_id": 3}, "order": "product_id"}
// 3) The stars of those products, in one request
{"table": "reviews", "select": "product_id,rating,comment", "where": {"product_id": "in.(5,12)"}, "order": "product_id,rating.desc"}
// 4) Her open orders, for the badge
{"table": "orders", "where": {"customer_id": 1, "status": "in.(new,paid)"}, "limit": 0}
